void EnvironmentView_BuildHumidity(DisplayService_View_t *view, bool valid,
                                   uint16_t humidity10, uint8_t comfort)
{
    char value[21U];
    if (view == NULL) { return; }
    DisplayService_ViewClear(view);
    (void)DisplayService_ViewSetLine(view, 0U, "SHT30 REAL HUMIDITY");
    if (valid)
    {
        (void)snprintf(value, sizeof(value), "%u.%u %% RH",
            (unsigned int)(humidity10 / 10U), (unsigned int)(humidity10 % 10U));
        (void)DisplayService_ViewSetLine(view, 2U, value);
        (void)DisplayService_ViewSetLine(view, 4U,
            (comfort == 1U) ? "DRY: RH < 40%" :
            ((comfort == 3U) ? "HUMID: RH > 60%" : "COMFORT: RH 40-60%"));
    }
    else { (void)DisplayService_ViewSetLine(view, 2U, "SENSOR UNKNOWN/STALE"); }
    (void)DisplayService_ViewSetLine(view, 5U, "POT: TEMP SETPOINT");
    (void)DisplayService_ViewSetLine(view, 6U, "LEFT/RIGHT PM2.5 SIM");
    (void)DisplayService_ViewSetLine(view, 7U, "SW1 HOLD: HOME CTRL");
}
